function teamRef(id) {
  const t = TEAMS.find((x) => x.id === id);
  return t ? { id: t.id, name: t.name } : { id, name: "Unknown" };
}

function mapFixture(f) {
  const league = LEAGUES.find((l) => l.id === f.leagueId);
  return {
    id: f.id,
    league: { id: league.id, name: league.name, country: league.country },
    home: teamRef(f.homeId),
    away: teamRef(f.awayId),
    kickoff: f.kickoff,
    status: f.status,
    venue: f.venue || "",
  };
}

export async function getLeagues() {
  return LEAGUES.map((l) => ({ ...l }));
}

export async function getUpcomingFixtures({ league, date, team } = {}) {
  let list = FIXTURES.filter((f) => f.status === "NS").map(mapFixture);
  if (league) list = list.filter((f) => f.league.id === league);
  if (team) list = list.filter((f) => f.home.id === team || f.away.id === team);
  if (date) list = list.filter((f) => f.kickoff.slice(0, 10) === date);
  return list;
}

/** All fixtures (played + scheduled), most recent first, for date browsing. */
export async function getAllFixtures({ league, date, team, limit } = {}) {
  let list = FIXTURES.map(mapFixture);
  if (league) list = list.filter((f) => f.league.id === league);
  if (team) list = list.filter((f) => f.home.id === team || f.away.id === team);
  if (date) list = list.filter((f) => f.kickoff.slice(0, 10) === date);
  list.sort((a, b) => new Date(b.kickoff) - new Date(a.kickoff));
  if (limit != null) list = list.slice(0, limit);
  return list;
}

export async function searchTeams(q) {
  const needle = String(q || "").trim().toLowerCase();
  if (!needle) return [];
  const leagueCountry = {};
  for (const l of LEAGUES) leagueCountry[l.id] = l.country;
  const teamLeague = {};
  for (const t of TEAMS) teamLeague[t.id] = t.leagueId;
  return TEAMS.filter((t) => t.name.toLowerCase().includes(needle)).map((t) => ({
    id: t.id,
    name: t.name,
    country: leagueCountry[teamLeague[t.id]] || "",
  }));
}

export async function getMatch(id) {
  const f = FIXTURES.find((x) => x.id === id);
  return f ? mapFixture(f) : null;
}

export async function getTeamStats(teamId) {
  const s = STATS[teamId];
  if (!s) return null;
  return { teamId, ...s };
}

export async function getLeagueAvgs(leagueId) {
  const ids = TEAMS.filter((t) => t.leagueId === leagueId).map((t) => t.id);
  let h = 0, a = 0, n = 0;
  for (const id of ids) {
    const s = STATS[id];
    if (s && s.homePlayed > 0 && s.awayPlayed > 0) {
      h += s.homeGF / s.homePlayed;
      a += s.awayGF / s.awayPlayed;
      n++;
    }
  }
  if (!n) return null;
  return { avgHomeGoals: h / n, avgAwayGoals: a / n, credible: true };
}

export async function getHeadToHead(homeId, awayId) {
  const past = FIXTURES.filter(
    (f) => f.status === "FT" &&
      ((f.homeId === homeId && f.awayId === awayId) ||
       (f.homeId === awayId && f.awayId === homeId))
  ).sort((x, y) => new Date(y.kickoff) - new Date(x.kickoff));
  let homeWins = 0, draws = 0, awayWins = 0;
  const lastMeetings = past.slice(0, 5).map((f) => {
    const hw = f.homeId === homeId;
    const hs = hw ? f.scoreH : f.scoreA, as = hw ? f.scoreA : f.scoreH;
    if (hs > as) homeWins++; else if (hs < as) awayWins++; else draws++;
    const nm = (id) => teamRef(id).name;
    return { date: f.kickoff.slice(0, 10), home: nm(f.homeId), away: nm(f.awayId), scoreH: f.scoreH, scoreA: f.scoreA };
  });
  // count all past meetings, not just last 5
  homeWins = 0; draws = 0; awayWins = 0;
  for (const f of past) {
    const hw = f.homeId === homeId;
    const hs = hw ? f.scoreH : f.scoreA, as = hw ? f.scoreA : f.scoreH;
    if (hs > as) homeWins++; else if (hs < as) awayWins++; else draws++;
  }
  return { played: past.length, homeWins, draws, awayWins, lastMeetings };
}

export async function getStandings(leagueId) {
  const out = {};
  for (const t of TEAMS.filter((x) => x.leagueId === leagueId)) {
    const s = STATS[t.id];
    if (s) out[t.id] = { position: s.position, played: s.played, points: s.points };
  }
  return out;
}

